<script setup>
import { ref, computed } from 'vue';
import OperatorPerusahaanLayout from '@/Layouts/OperatorPerusahaanLayout.vue';
import { Head, Link } from '@inertiajs/vue3';

defineOptions({ layout: OperatorPerusahaanLayout });

const riwayats = ref([
  { id: 1, kode_tagihan: 'INV-202505-001', karyawan: 'Ahmad', nominal: 12500, bukti: null, status_insentif: 'disetujui', status_pembayaran: 'lunas', bukti_cair: null, deskripsi: 'Kolektor - Tunai 5% | Tagihan Rp250.000', alasan: null, created_at: '2025-05-08' },
  { id: 2, kode_tagihan: 'INV-202505-002', karyawan: 'Siti', nominal: 12000, bukti: null, status_insentif: 'menunggu', status_pembayaran: 'belum lunas', bukti_cair: null, deskripsi: 'Kolektor - Transfer 3% | Tagihan Rp400.000', alasan: null, created_at: '2025-05-10' },
  { id: 3, kode_tagihan: 'INV-202505-003', karyawan: 'Budi', nominal: 75000, bukti: null, status_insentif: 'ditolak', status_pembayaran: 'lunas', bukti_cair: null, deskripsi: 'Bonus Tunggakan 10% | Tagihan Rp750.000', alasan: 'Data pembayaran tidak valid, duplikasi', created_at: '2025-05-01' },
  { id: 4, kode_tagihan: 'INV-202505-004', karyawan: 'Rudi', nominal: 7500, bukti: null, status_insentif: 'disetujui', status_pembayaran: 'lunas', bukti_cair: 'transfer_bca_20250510.jpg', deskripsi: 'Kolektor - Tunai 5% | Tagihan Rp150.000', alasan: null, created_at: '2025-04-20' },
  { id: 5, kode_tagihan: 'INV-202504-001', karyawan: 'Ahmad', nominal: 7500, bukti: null, status_insentif: 'menunggu', status_pembayaran: 'lunas', bukti_cair: null, deskripsi: 'Kolektor - Tunai 5% | Tagihan Rp150.000', alasan: null, created_at: '2025-03-25' },
]);

const searchInput = ref(''); const search = ref(''); const statusInsentifFilter = ref(''); const statusPembayaranFilter = ref(''); const currentPage = ref(1); const perPage = ref(5); const perPageOptions = [5, 10, 25, 50, 100];
const selectedIds = ref([]); const selectAll = ref(false); const sortFields = ref([]); const selectedItem = ref(null);
const showDetailModal = ref(false); const showDeleteModal = ref(false);

function applySearch() { search.value = searchInput.value; currentPage.value = 1; }
function clearSearch() { searchInput.value = ''; search.value = ''; currentPage.value = 1; }
function applyStatusInsentifFilter(s) { statusInsentifFilter.value = s; currentPage.value = 1; }
function applyStatusPembayaranFilter(s) { statusPembayaranFilter.value = s; currentPage.value = 1; }
function changePerPage(n) { perPage.value = n; currentPage.value = 1; }
function toggleSelectAll() { selectedIds.value = selectAll.value ? paginatedRiwayats.value.map(r => r.id) : []; }
function toggleSelect(id) { const i = selectedIds.value.indexOf(id); i === -1 ? selectedIds.value.push(id) : selectedIds.value.splice(i, 1); selectAll.value = selectedIds.value.length === paginatedRiwayats.value.length; }
function bulkDelete() { riwayats.value = riwayats.value.filter(r => !selectedIds.value.includes(r.id)); selectedIds.value = []; selectAll.value = false; }
function sort(field) { const e = sortFields.value.findIndex(s => s.field === field); if (e !== -1) { if (sortFields.value[e].dir === 'asc') sortFields.value[e].dir = 'desc'; else sortFields.value.splice(e, 1); } else sortFields.value.push({ field, dir: 'asc' }); }
function sortIcon(f) { const s = sortFields.value.find(s => s.field === f); if (!s) return 'fa-sort'; return s.dir === 'asc' ? 'fa-sort-up' : 'fa-sort-down'; } function sortOrder(f) { const i = sortFields.value.findIndex(s => s.field === f); return i !== -1 ? i + 1 : null; }
function statusInsentifBadge(s) { if (s === 'disetujui') return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400'; if (s === 'menunggu') return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'; return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'; }
function statusPembayaranBadge(s) { return s === 'lunas' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'; }
function formatRupiah(n) { return 'Rp ' + Number(n).toLocaleString('id-ID'); }

const filteredRiwayats = computed(() => {
  let r = [...riwayats.value]; if (search.value) { const q = search.value.toLowerCase(); r = r.filter(x => x.kode_tagihan.toLowerCase().includes(q) || x.karyawan.toLowerCase().includes(q)); }
  if (statusInsentifFilter.value) r = r.filter(x => x.status_insentif === statusInsentifFilter.value);
  if (statusPembayaranFilter.value) r = r.filter(x => x.status_pembayaran === statusPembayaranFilter.value);
  if (sortFields.value.length > 0) r.sort((a, b) => { for (const s of sortFields.value) { let av = a[s.field], bv = b[s.field]; if (s.field === 'nominal') { av = Number(av); bv = Number(bv); } if (av != bv) return (typeof av === 'string' ? av.localeCompare(bv) : av - bv) * (s.dir === 'asc' ? 1 : -1); } return 0; }); return r;
});
const totalPages = computed(() => Math.ceil(filteredRiwayats.value.length / perPage.value) || 1);
const paginatedRiwayats = computed(() => { const s = (currentPage.value - 1) * perPage.value; return filteredRiwayats.value.slice(s, s + perPage.value); });
const visiblePages = computed(() => { const p = []; const t = totalPages.value; const c = currentPage.value; let st = Math.max(1, c - 2); let en = Math.min(t, c + 2); if (en - st < 4) { if (st === 1) en = Math.min(t, st + 4); else st = Math.max(1, en - 4); } for (let i = st; i <= en; i++) p.push(i); return p; });

function openDetail(r) { selectedItem.value = r; showDetailModal.value = true; }
function openDelete(r) { selectedItem.value = r; showDeleteModal.value = true; }
function confirmDelete() { riwayats.value = riwayats.value.filter(r => r.id !== selectedItem.value.id); showDeleteModal.value = false; if (paginatedRiwayats.value.length === 0 && currentPage.value > 1) currentPage.value--; }
function goToPage(p) { currentPage.value = Math.max(1, Math.min(p, totalPages.value)); }
</script>

